"""Export the choreography JSONs to RP2040/dance_data.py (MicroPython data).

python3 export_rp2040.py <path/to/RP2040/dance_data.py>
"""
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, "out")


def main(dst):
    lines = [
        "# Coglet dance choreography -- GENERATED by dj/export_rp2040.py from the",
        "# same score that renders the music. Do not edit by hand; re-run the",
        "# exporter after changing a track so music and dance stay in sync.",
        "#",
        "# moves: (time_ms_from_music_start, move, arg)",
        "",
        "TRACKS = {",
    ]
    for name in ("mecha", "evil", "cat"):
        with open(os.path.join(OUT, name + "_choreo.json")) as f:
            c = json.load(f)
        lines.append('    "{}": {{'.format(name))
        lines.append('        "bpm": {},'.format(c["bpm"]))
        lines.append('        "duration_ms": {},'.format(c["duration_ms"]))
        lines.append('        "moves": (')
        for m in c["moves"]:
            arg = m["arg"]
            if isinstance(arg, dict):
                arg = arg.get("seconds")
            lines.append("            ({}, {!r}, {!r}),".format(m["t_ms"], m["move"], arg))
        lines.append("        ),")
        lines.append("    },")
    lines.append("}")
    with open(dst, "w") as f:
        f.write("\n".join(lines) + "\n")
    print("wrote", dst)


if __name__ == "__main__":
    main(sys.argv[1])
